	invariant strictSorted(v[..])
	invariant strictSorted(w[..])
	invariant forall k::0<=k<i ==> v[k] in w[..j] 
	invariant i< (n) - 1  ==> !(v[i] in w[..j])
	decreases w.Length-j
	decreases v.Length-i
